/**
 * The read-only catalog: foods, swap groups and meal plans.
 * Foods ship inside the app (generated by pipeline/consumer/), so search works offline:
 *   - the EVERYDAY tier (~3,000 foods) loads at startup;
 *   - the EXTENDED tier (~15,000 foods, ~5 MB) loads on demand: `ensureExtendedLoaded()`.
 * FOODS / FOOD_INDEX / foodSearch are the same objects before and after; extended foods are appended in place and the
 * search index is rebuilt, so callers that hold a reference keep working.
 * Plans ship as a starter set and are refreshed from Supabase when configured.
 */
import everydayJson from '@/data/foods.everyday.json';
import legacyIdMapJson from '@/data/legacyIdMap.json';
import { decodeFoods, type FoodBundle } from '@/data/loadFoods';
import plansJson from '@/data/plans.json';
import swapGroupsJson from '@/data/swapGroups.json';
import { FoodSearch } from '@/engine/search';
import type { Food, MealPlan, SwapGroup } from '@/engine/types';
import type { FoodResolver } from '@/import/planWorkbook';

/** old (hand-made sample) food id -> id in the rebuilt library. Plans, logs and dislikes saved before the rebuild still resolve. */
export const LEGACY_ID_MAP: Readonly<Record<string, string>> = legacyIdMapJson as Record<string, string>;

/** A Map whose `get`/`has` also answer to the legacy ids. Iteration and size only see current foods. */
export class FoodIndex extends Map<string, Food> {
  private readonly legacy: Readonly<Record<string, string>>;
  constructor(foods: Food[], legacy: Readonly<Record<string, string>> = LEGACY_ID_MAP) {
    super();
    this.legacy = legacy;
    for (const f of foods) this.set(f.id, f);
  }
  override get(id: string): Food | undefined {
    const direct = super.get(id);
    if (direct) return direct;
    const to = this.legacy[id];
    return to ? super.get(to) : undefined;
  }
  override has(id: string): boolean {
    return super.has(id) || (id in this.legacy && super.has(this.legacy[id]));
  }
}

export const FOODS: Food[] = decodeFoods(everydayJson as unknown as FoodBundle, 'everyday');
export const FOOD_INDEX = new FoodIndex(FOODS);
export const SWAP_GROUPS = swapGroupsJson as unknown as SwapGroup[];
export const SWAP_INDEX = new Map(SWAP_GROUPS.map((g) => [g.key, g]));
export const BUNDLED_PLANS = plansJson as unknown as MealPlan[];

// the old ids a rebuilt food answers to (so `isDisliked`, favourites etc. saved under an old id keep matching)
for (const [oldId, newId] of Object.entries(LEGACY_ID_MAP)) {
  const f = FOOD_INDEX.get(newId);
  if (f) (f.legacyIds ??= []).push(oldId);
}

export const foodSearch = new FoodSearch(FOODS);

export const food = (id: string) => FOOD_INDEX.get(id);

// ── lazy extended tier ──────────────────────────────────────────────────────

let extendedLoaded = false;
let extendedPromise: Promise<void> | undefined;
const listeners = new Set<() => void>();

export const isExtendedLoaded = () => extendedLoaded;

/** Subscribe to "the catalog changed" (extended tier arrived). Returns the unsubscribe function. */
export function subscribeCatalog(cb: () => void): () => void {
  listeners.add(cb);
  return () => listeners.delete(cb);
}

/** Add the extended tier to FOODS / FOOD_INDEX and rebuild the search index. Safe to call any number of times. */
export function ensureExtendedLoaded(): Promise<void> {
  if (extendedLoaded) return Promise.resolve();
  extendedPromise ??= import('@/data/foods.extended.json').then((mod) => {
    if (extendedLoaded) return;
    const ext = decodeFoods((mod.default ?? mod) as unknown as FoodBundle, 'extended');
    for (const f of ext) {
      if (FOOD_INDEX.has(f.id)) continue;
      FOODS.push(f);
      FOOD_INDEX.set(f.id, f);
    }
    foodSearch.setFoods(FOODS);
    extendedLoaded = true;
    listeners.forEach((cb) => cb());
  });
  // a failed load (e.g. the single-file web demo ships without the lazy chunk) leaves the everyday tier working and may be retried
  extendedPromise.catch(() => {
    extendedPromise = undefined;
  });
  return extendedPromise;
}

export function swapCandidates(groupKey: string | undefined): Food[] {
  const g = groupKey ? SWAP_INDEX.get(groupKey) : undefined;
  return (g?.foodIds ?? []).map((id) => FOOD_INDEX.get(id)).filter((f): f is Food => !!f);
}

export const foodResolver: FoodResolver = {
  byId: (id) => FOOD_INDEX.get(id),
  search: (name, limit = 3) =>
    foodSearch.search(name, { limit, includeRare: true }).map((h) => ({ id: h.food.id, name: h.food.name, score: h.score })),
};

export const isFattyFish = (id: string) => !!FOOD_INDEX.get(id)?.tags?.includes('fatty_fish');
